@echo off
echo ============================================
echo   Gemini Watermark Remover - Batch Process
echo ============================================
echo.
echo Input folder:  %~dp0input
echo Output folder: %~dp0output
echo.

:: Check if input folder has files
dir /b "%~dp0input\*" >nul 2>&1
if errorlevel 1 (
    echo ERROR: No files found in the "input" folder!
    echo Put your watermarked images/videos in: %~dp0input
    echo.
    pause
    exit /b 1
)

:: Count files
set /a count=0
for %%f in ("%~dp0input\*") do set /a count+=1
echo Found %count% file(s) to process.
echo.
echo Starting watermark removal...
echo.

gwr remove "%~dp0input" --out-dir "%~dp0output"

echo.
if errorlevel 1 (
    echo ============================================
    echo   DONE - Some files may have had errors.
    echo   Check the output folder for results.
    echo ============================================
) else (
    echo ============================================
    echo   DONE - All files processed successfully!
    echo   Clean files saved to: %~dp0output
    echo ============================================
)
echo.
pause

